import { useState, useEffect, useRef } from 'react';

const SearchBar = ({ onSearch, placeholder = 'Search gold, tech, and more...' }) => {
  const [value, setValue] = useState('');
  const debounceRef = useRef(null);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      onSearch(value);
    }, 400);
    return () => clearTimeout(debounceRef.current);
  }, [value]);

  return (
    <div className="relative group">
      <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xl pointer-events-none">
        search
      </span>
      <input
        type="text"
        value={value}
        onChange={(e) => setValue(e.target.value)}
        placeholder={placeholder}
        className="w-full bg-gray-50 dark:bg-gray-800 border-none rounded-xl py-2 pl-10 pr-10 text-sm focus:ring-2 focus:ring-primary-container transition-all outline-none dark:text-white dark:placeholder-gray-400"
      />
      {value && (
        <button
          onClick={() => { setValue(''); onSearch(''); }}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
        >
          <span className="material-symbols-outlined text-base">close</span>
        </button>
      )}
    </div>
  );
};

export default SearchBar;

