          Sign In
        </Link>
      </div>
    );
  }

  return (
    <div className="bg-surface-container-lowest dark:bg-gray-950 min-h-screen">
      <main className="max-w-[1280px] mx-auto px-6 py-8">
        <div className="flex flex-col lg:flex-row gap-6">

          {/* Cart Items */}
          <div className="flex-grow space-y-4">
            <div className="flex items-center justify-between mb-6">
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Your Cart</h1>
              {cartItems.length > 0 && (
                <span className="text-gray-500 text-sm font-medium">{cartItems.length} {cartItems.length === 1 ? 'Item' : 'Items'}</span>
              )}
            </div>

            {loading && (
              <div className="space-y-4">
                {[...Array(3)].map((_, i) => (
                  <div key={i} className="bg-gray-100 dark:bg-gray-800 rounded-xl h-36 animate-pulse" />
                ))}
              </div>
            )}

            {!loading && cartItems.length === 0 && (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-24 h-24 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-6">
                  <span className="material-symbols-outlined text-5xl text-gray-400">shopping_cart</span>
                </div>
                <h3 className="text-xl font-bold text-gray-700 dark:text-gray-300 mb-2">Your cart is empty</h3>
                <p className="text-gray-500 text-sm mb-6">Looks like you haven't added anything yet</p>
                <Link to="/products" className="bg-primary-container text-on-primary-container font-semibold px-8 py-3 rounded-xl hover:shadow-md transition-all">
                  Start Shopping
                </Link>
              </div>
            )}

            {!loading && cartItems.map((item) => <CartItem key={item.id} item={item} />)}

            {!loading && cartItems.length > 0 && (
              <div className="pt-4">
                <Link to="/products" className="flex items-center gap-2 font-semibold text-primary hover:gap-4 transition-all text-sm">
                  <span className="material-symbols-outlined">arrow_back</span>
                  Continue Shopping
                </Link>
              </div>
            )}
          </div>

          {/* Order Summary */}
          {cartItems.length > 0 && (
            <aside className="w-full lg:w-[400px] flex-shrink-0">
              <div className="bg-white dark:bg-gray-900 rounded-xl p-6 shadow-[0px_4px_20px_rgba(0,0,0,0.05)] border border-gray-100 dark:border-gray-800 sticky top-24">
                <h2 className="text-2xl font-bold mb-8 text-gray-900 dark:text-white">Order Summary</h2>

                <div className="space-y-4 border-b border-gray-100 dark:border-gray-700 pb-6">
                  <div className="flex justify-between text-gray-600 dark:text-gray-400 text-sm">
                    <span>Subtotal</span>
                    <span>${cartTotal.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-gray-600 dark:text-gray-400 text-sm">
                    <span>Estimated Tax (8%)</span>
                    <span>${tax.toFixed(2)}</span>
                  </div>
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-600 dark:text-gray-400">Shipping</span>
                    {shipping === 0
                      ? <span className="text-primary font-semibold">FREE</span>
                      : <span className="text-gray-600 dark:text-gray-400">${shipping.toFixed(2)}</span>
                    }
                  </div>
                </div>

                <div className="py-6">
                  <div className="flex justify-between font-black text-2xl text-gray-900 dark:text-white">
                    <span>Total</span>
                    <span>${grandTotal.toFixed(2)}</span>
                  </div>
                  <p className="text-xs text-gray-400 mt-1">Inclusive of all taxes and fees</p>
                </div>

                {/* Promo Code */}
                <div className="flex gap-2 mb-4">
                  <input
                    type="text"
                    placeholder="Promo Code"
                    className="flex-grow bg-gray-50 dark:bg-gray-800 border-none rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-primary-container outline-none dark:text-white dark:placeholder-gray-400"
