import { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { fetchProducts } from '../services/api';
import ProductCard from '../components/ProductCard';
import SearchBar from '../components/SearchBar';

const CATEGORIES = ['All', 'Fine Jewelry', 'Watches', 'Investment', 'Electronics', 'Audio', 'Photography', 'Computing'];
const SORT_OPTIONS = [
  { value: '', label: 'Popularity' },
  { value: 'price_asc', label: 'Price: Low to High' },
  { value: 'price_desc', label: 'Price: High to Low' },
  { value: 'rating', label: 'Top Rated' },
  { value: 'newest', label: 'Newest Arrivals' },
];

const ProductListingPage = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const search = searchParams.get('search') || '';
  const category = searchParams.get('category') || 'All';
  const sort = searchParams.get('sort') || '';
  const [maxPrice, setMaxPrice] = useState(25000);
  const [priceFilter, setPriceFilter] = useState(25000);

  const loadProducts = async () => {
    setLoading(true); setError('');
    try {
      const params = {};
      if (search) params.search = search;
      if (category && category !== 'All') params.category = category;
      if (sort) params.sort = sort;
      if (priceFilter < 25000) params.maxPrice = priceFilter;

      const res = await fetchProducts(params);
      setProducts(res.data.products || []);
      setTotal(res.data.total || 0);
    } catch (err) {
      setError('Failed to load products. Please ensure the backend is running.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadProducts(); }, [search, category, sort, priceFilter]);

  const updateParam = (key, val) => {
    const params = Object.fromEntries(searchParams.entries());
    if (val) params[key] = val; else delete params[key];
    setSearchParams(params);
  };

  return (
    <div className="bg-surface-container-lowest dark:bg-gray-950 min-h-screen">
      <main className="max-w-[1280px] mx-auto px-6 py-6 flex flex-col md:flex-row gap-6">

        {/* Sidebar Filters */}
        <aside className="w-full md:w-64 flex-shrink-0 space-y-8">

          {/* Category Filter */}
          <section>
            <h3 className="font-semibold text-lg text-gray-900 dark:text-white mb-4">Category</h3>
            <div className="space-y-2">
              {CATEGORIES.map((cat) => (
                <label key={cat} className="flex items-center gap-3 cursor-pointer group">
                  <input
                    type="radio"
                    name="category"
                    checked={category === cat}
                    onChange={() => updateParam('category', cat === 'All' ? '' : cat)}
                    className="w-4 h-4 text-primary focus:ring-primary-container border-gray-300 cursor-pointer"
                  />
                  <span className={`text-sm group-hover:text-primary transition-colors ${category === cat ? 'text-primary font-semibold' : 'text-gray-700 dark:text-gray-300'}`}>
                    {cat}
                  </span>
                </label>
              ))}
            </div>
          </section>

          {/* Price Range */}
          <section>
            <h3 className="font-semibold text-lg text-gray-900 dark:text-white mb-4">Price Range</h3>
            <div className="px-2">
              <input
                type="range"
                min={0}
                max={25000}
                step={100}
                value={priceFilter}
                onChange={(e) => setPriceFilter(Number(e.target.value))}
                className="w-full h-2 bg-gray-200 rounded-full appearance-none accent-primary-container cursor-pointer"
              />
              <div className="flex justify-between mt-2">
                <span className="text-xs text-gray-500">$0</span>
                <span className="text-xs font-semibold text-primary">${priceFilter.toLocaleString()}</span>
                <span className="text-xs text-gray-500">$25,000+</span>
              </div>
            </div>
          </section>

          {/* Rating Filter */}
          <section>
            <h3 className="font-semibold text-lg text-gray-900 dark:text-white mb-4">Customer Ratings</h3>
            {[4, 3].map((r) => (
              <button key={r} className="flex items-center gap-2 hover:bg-gray-50 dark:hover:bg-gray-800 w-full p-2 rounded-lg transition-colors">
                <div className="flex text-primary-container">
                  {[...Array(5)].map((_, i) => (
                    <span key={i} className={`material-symbols-outlined text-base ${i < r ? 'icon-filled' : ''}`}>star</span>
                  ))}
                </div>
                <span className="text-sm text-gray-500">& Up</span>
              </button>
            ))}
          </section>

          <button onClick={loadProducts} className="w-full bg-primary-container text-on-primary-container py-3 rounded-xl font-semibold text-sm active:scale-[0.98] transition-transform hover:shadow-md">
            Apply Filters
          </button>
        </aside>

        {/* Product Grid */}
        <div className="flex-1">
          {/* Toolbar */}
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
                {category !== 'All' ? category : search ? `Results for "${search}"` : 'All Products'}
              </h1>
              <p className="text-sm text-gray-500 mt-1">Showing {total} products</p>
            </div>
            <div className="flex items-center gap-3">
              <span className="text-sm font-medium text-gray-500">Sort by:</span>
              <select
                value={sort}
                onChange={(e) => updateParam('sort', e.target.value)}
                className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl text-sm py-2 px-4 focus:ring-2 focus:ring-primary-container outline-none dark:text-white"
              >
                {SORT_OPTIONS.map((opt) => (
                  <option key={opt.value} value={opt.value}>{opt.label}</option>
                ))}
              </select>
            </div>
          </div>

          {/* States */}
          {loading && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {[...Array(6)].map((_, i) => (
                <div key={i} className="bg-gray-100 dark:bg-gray-800 rounded-xl h-80 animate-pulse" />
              ))}
            </div>
          )}

          {error && (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <span className="material-symbols-outlined text-5xl text-red-400 mb-4">error_outline</span>
              <p className="text-gray-600 dark:text-gray-400">{error}</p>
            </div>
          )}

          {!loading && !error && products.length === 0 && (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <span className="material-symbols-outlined text-6xl text-gray-300 mb-4">search_off</span>
              <h3 className="text-xl font-semibold text-gray-600 dark:text-gray-400 mb-2">No products found</h3>
              <p className="text-gray-500 text-sm">Try adjusting your filters or search term</p>
            </div>
          )}

          {!loading && !error && products.length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {products.map((p) => <ProductCard key={p.id} product={p} />)}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default ProductListingPage;

